      shots5: [["/assets/log/partner-top-lists.png", "Un mensaje de partner con los tops de la semana y de siempre"], ["/assets/log/new-variables.png", "Un mensaje que usa las variables nuevas del servidor y del miembro"], ["/assets/log/purge-all-channels.png", "La confirmación de /purge en todos los canales"], ["/assets/log/mhistory.png", "La respuesta de /mhistory"], ["/assets/log/case-detail.png", "La tarjeta de un caso con el icono del martillo"]],
