for (const lang of locales) {
  for (const category of ui[lang].commandsPage.categories) {
    (category.cmds as CommandRow[]).push(...commandRows(category.id, lang));
  }
  // One section for each service of the Integrations category (Last.fm, Twitch, Minecraft...), after the others.
  (ui[lang].commandsPage.categories as unknown as unknown[]).push(...integrationCategories(lang));
}

export function useTranslations(lang: Locale) {
  return ui[lang];
}

/**
 * Release/blog entries newest-first. Sorted on the `iso` field rather than the human `date`
 * string, which is localized prose ("July 22, 2026", "22 de julio de 2026") and unsortable.
 * Entries with no date yet (roadmap "Coming soon" items) always sit at the end.
 */
export function sortedReleases(lang: Locale) {
  return [...ui[lang].releases.items].sort((a, b) => {
    if (!a.iso && !b.iso) return 0;
    if (!a.iso) return 1;
    if (!b.iso) return -1;
    return b.iso.localeCompare(a.iso);
  });
}

export function getLangFromUrl(url: URL): Locale {
  const [, first] = url.pathname.split('/');
  if (first === 'es') return 'es';
  if (first === 'pt-br') return 'pt-BR';
  return 'en';
}
